  "prompt.example.6": "ᐃᓚᓕᐅᑎᓗᒋᑦ ᐃᒡᓗᐃᑦ ᖃᐅᔨᓴᕈᑏᑦ ᐊᑐᖅᑎᓄᑦ ᐱᔨᑦᑎᕋᐅᑎᓄᑦ",
  "prompt.example.7": "ᐋᖅᑭᒋᐊᕐᓗᒍ ᑖᓐᓇ ᐊᐅᓚᓂᐅᔪᖅ ᐅᖃᓕᒫᖅᑕᐅᔪᓐᓇᕐᓂᖅᓴᐅᖁᓪᓗᒍ",
  "prompt.example.8": "ᖃᓄᖅ ᑐᑭᖃᖅᐸ ᑖᓐᓇ ᑕᒻᒪᖅᓯᒪᔪᖅ?",
  "prompt.example.9": "ᐃᑲᔪᓚᐅᙵ ᐋᖅᑭᒃᓱᐃᓗᖓ ᑖᔅᓱᒥᖓ ᐱᔾᔪᑎᒥᒃ",
  "prompt.example.10": "ᓴᖅᑭᑦᑎᓗᓂ API ᑎᑎᕋᖅᓯᒪᔪᓂᒃ",
  "prompt.example.11": "ᐱᐅᓯᒋᐊᕐᓗᒋᑦ ᖃᕆᑕᐅᔭᒃᑯᑦ ᑐᖅᑯᖅᑕᐅᓯᒪᔪᑦ ᐊᐱᖅᑯᑏᑦ",
  "prompt.example.12": "ᐃᓚᓕᐅᑎᓗᒍ ᑎᑎᕋᖅᑕᐅᓯᒪᔪᖅ ᓇᓗᓇᐃᖅᑕᐅᓂᖓ",
  "prompt.example.13": "ᓄᑖᒥᒃ ᓴᖅᑭᑦᑎᓗᓂ...",
  "prompt.example.14": "ᖃᓄᖅ ᑖᓐᓇ ᐱᓕᕆᐊᖅ ᓴᖅᑭᑎᒍᓐᓇᖅᐸᕋ?",
  "prompt.example.15": "ᕿᒥᕐᕈᓗᒍ ᒪᓕᒐᕋ ᐱᐅᓂᖅᐹᓂᒃ ᐊᑐᖅᑕᐅᕙᒃᑐᓂᒃ",
  "prompt.example.16": "ᐃᓚᓕᐅᑎᓗᒍ ᑕᒻᒪᖅᓯᒪᔪᓂᒃ ᑲᒪᒋᔭᖃᕐᓂᖅ ᑖᔅᓱᒧᖓ ᐊᐅᓚᓂᐅᔪᒧᑦ",
  "prompt.example.17": "ᓇᓗᓇᐃᔭᕐᓗᒍ ᑖᓐᓇ regex ᐋᖅᑭᒃᓯᒪᓂᖓ",
  "prompt.example.18": "ᐋᖅᑭᒃᓱᕐᓗᒍ ᑖᓐᓇ ᑎᑎᕋᐅᓯᕐᒧᑦ",
  "prompt.example.19": "ᐃᓚᓕᐅᑎᓗᒍ ᓇᐹᖅᑐᓕᕆᓂᖅ ᓇᓗᓇᐃᒃᑯᑕᓕᒫᒥ",
  "prompt.example.20": "ᑭᓱᑦ ᑐᕚᖃᖅᑐᑦ ᐱᑐᖃᐅᓕᖅᐸᑦ?",
  "prompt.example.21": "ᐃᑲᔪᓚᐅᙵ ᑎᑎᕋᕐᓗᖓ ᓄᑦᑎᕆᓂᕐᒧᑦ ᑎᑎᕋᖅᓯᒪᔪᒥᒃ",
  "prompt.example.22": "ᐊᑐᓕᖅᑎᑦᑎᓗᑎᑦ ᑐᖅᑯᐃᓂᕐᒥᒃ ᑖᔅᓱᒧᖓ ᐃᓱᓕᕝᕕᖓᓄᑦ",
  "prompt.example.23": "ᐃᓚᓕᐅᑎᓗᒍ ᒪᒃᐱᒐᖅ ᑖᔅᓱᒧᖓ ᑎᑎᕋᖅᓯᒪᔪᓄᑦ",
